from lib import *
S = SS('n42')
steps = [
    step("Recovery 就是一个 defer + recover 的中间件:recover 到 panic 后先判断是不是“断管”类错误(errors.Is 命中 EPIPE、ECONNRESET 或 http.ErrAbortHandler);再写日志(断管:只写 panic 值和请求转储;debug 模式:请求转储 + panic + 栈;release 模式:panic + 栈);最后断管就 c.Error(err) + c.Abort()(注释:连接已死,写不了状态),否则调用恢复函数 handle(默认 AbortWithStatus(500))。", t=tl(S(1)), mark=lidx(S(1), 'syscall.EPIPE', 'syscall.ECONNRESET', 'http.ErrAbortHandler', 'c.Abort()'), done=lidx(S(1), 'handle(c, rec)', 'secureRequestDump(c.Request)', 'only the Authorization header is sanitized'), kv=KV([['断管错误', 'EPIPE / ECONNRESET / ErrAbortHandler'], ['普通 panic', 'handle(c, rec),默认 500'], ['日志', 'release:panic + 栈;debug:再加请求转储']], ['断管错误'])),
    step("默认 Recovery(release 模式)遇到 panic(\"boom 的细节\"):客户端得到状态 500、空正文、没有 Content-Type;日志写 [Recovery] 时间 panic recovered:、panic 值,然后是带源码行的栈帧(共 23 行,第一帧就是 main.go:24 的那行 panic,下面是 Context.Next、Recovery 自己);release 模式不含请求转储;panic 之后同一个引擎继续正常服务(/ok → 200)。", t=tl(S(2)), mark=lidx(S(2), '状态 500', 'panic recovered', 'boom 的细节', 'main.func1'), done=lidx(S(2), '/ok → 200'), kv=KV([['响应', '500 + 空正文'], ['日志', 'panic 值 + 带源码行的栈'], ['之后', '引擎继续服务']], ['响应'])),
    step("debug 模式的日志在 panic 值前多出一份请求转储(GET /boom?x=1 HTTP/1.1、Host 和所有头),其中 Authorization 头被打码成 Authorization: *,令牌 SECRET-TOKEN 没有出现;但 Cookie: sid=abc 和 X-Api-Key: k-123 原样出现在日志里——源码注释写明只处理 Authorization。debug 模式下的日志共 30 行。", t=tl(S(3)), mark=lidx(S(3), 'Authorization: *', 'Cookie: sid=abc', 'X-Api-Key: k-123', '含 SECRET-TOKEN: false'), done=lidx(S(3), 'GET /boom?x=1 HTTP/1.1'), b=bars([['Authorization 的令牌', 0, '被打码'], ['Cookie 的值', 1, '原样出现'], ['X-Api-Key 的值', 1, '原样出现']], 1, done=[0], mark=[1, 2]), kv=KV([['Authorization', '被打码为 *'], ['Cookie / 其它头', '原样写进日志'], ['结论', 'debug 日志不能直接发到外部系统']], ['结论'])),
    step("handler(CustomRecovery 的第二个参数)收到的 err 就是 panic 的原值:字符串 → string;errors.New → *errors.errorString;自定义结构体 → main.MyErr;panic(nil) → *runtime.PanicNilError(runtime error: panic called with nil argument);写 nil map → runtime.plainError;下标越界 → runtime.boundsError;空指针解引用、整数除零 → runtime.errorString。", t=tl(S(4)), mark=lidx(S(4), 'PanicNilError', 'boundsError', 'plainError'), done=lidx(S(4), 'string → text', 'main.MyErr'), kv=KV([['panic(nil)', '*runtime.PanicNilError(Go 1.21+)'], ['运行时错误', 'boundsError / errorString / plainError'], ['其它值', '原样传给恢复函数']], ['panic(nil)'])),
    step("自定义恢复函数返回 JSON:/early 得到 500 与 {\"error\":\"内部错误\",\"id\":\"req-1\"};如果 panic 之前已经写出了前半段(/late):状态仍是 200,正文是“已经写出的前半段”后面直接拼上 JSON——状态改不了,而且响应体被破坏;断管类错误(panic(http.ErrAbortHandler)、panic(syscall.EPIPE)、被 %w 包装的 ECONNRESET)不记栈(只有 panic 值和请求转储)、不调用自定义函数(累计仍是 2 次)、状态保持 200,c.Errors 里有 1 条。", t=tl(S(5)), mark=lidx(S(5), '/late', '/abort', '/epipe', '/wrapped'), done=lidx(S(5), '/early'), kv=KV([['已写出后 panic', '状态改不了,JSON 拼在半截正文后面'], ['断管错误', '不记栈、不调自定义函数、c.Errors +1'], ['/early', '自定义函数写出 500 JSON']], ['已写出后 panic'])),
]
A = mkartn('n42', 42, 'Gin,Recovery,panic,崩溃恢复,日志,Go,真实验证,动画演示',
    '在 Gin v1.12.0 里实测 Recovery:panic 之后客户端是 500 加空正文,日志带栈,引擎继续服务;debug 模式多出请求转储但只给 Authorization 打码(Cookie、X-Api-Key 原样出现);恢复函数收到 panic 的原值(包括 panic(nil) 的 *runtime.PanicNilError);EPIPE / ECONNRESET / http.ErrAbortHandler 走断管分支,不记栈、不调自定义函数。',
    'Recovery 捕获 panic 之后到底做了什么?客户端看到什么、日志里有什么、哪些头会被打码?断管错误为什么特殊对待?这篇从源码的 30 行出发,用 8 种 panic 值、debug 与 release 两种模式把它的行为一项项核对。',
    [('500 + 空正文', '默认 Recovery 之后客户端看到的响应'), ('Authorization: *', 'debug 日志里只有这个头被打码,Cookie 与 X-Api-Key 原样出现'), ('3 类', 'EPIPE / ECONNRESET / ErrAbortHandler 走断管分支:不记栈、不调自定义函数')],
    [('骨架', '<p>Recovery 是 <code>defer + recover</code> 加三个分支:判断是不是断管错误、写日志、写响应。普通 panic 交给恢复函数(默认 <code>AbortWithStatus(500)</code>);断管错误则只 <code>c.Error</code> 并 <code>Abort</code>,因为连接已经没法再写状态了。</p>'),
     ('默认行为', '<p>客户端拿到 500 和空正文,没有 Content-Type。日志默认写到 <code>gin.DefaultErrorWriter</code>(标准错误),内容是 panic 值和带源码行的栈,栈里第一帧就是出事的那一行。<code>panic</code> 只影响当前请求,同一个引擎继续服务。</p>'),
     ('debug 日志里的敏感信息', '<p>debug 模式的日志会附上请求转储,其中只有 <code>Authorization</code> 头被替换成 <code>*</code>(源码注释写明了“目前只处理 Authorization”),<code>Cookie</code>、<code>X-Api-Key</code> 等头原样输出。线上要用 release 模式(它不输出请求转储),并且别把 debug 日志送进共享的日志系统。</p>'),
     ('panic 的值', '<p>恢复函数拿到的 <code>err</code> 就是 panic 的原值,可能是字符串、error、你自己的类型,或者各种运行时错误(下标越界、空指针、除零、写 nil map)。<code>panic(nil)</code> 在 Go 1.21 以后会变成 <code>*runtime.PanicNilError</code>,所以 <code>err != nil</code> 的判断不会漏掉它。</p>'),
     ('自定义恢复与边界', '<p>常见的自定义是返回统一的 JSON 错误体。注意:如果 panic 之前响应已经写出了一部分,状态码改不了,JSON 会拼在已发出的半截正文后面——这种响应是被破坏的,需要在更早的地方避免(先构造完整响应再一次性写出)。断管类 panic 不会调用你的函数,也不记栈。</p>')],
    steps,
    [ENV_N_GIN + '。日志写入 bytes.Buffer(栈帧里的地址被替换成 0x…,路径经过整理);请求用 httptest 直接调用 ServeHTTP;debug 模式用 GIN_MODE=debug 运行;每种情形各一次',
     '没有验证:真实断管(客户端中途关闭连接)时 Gin 是否会 panic(写入失败通常只返回 error,不会 panic,没有测);goroutine 里的 panic(Recovery 管不到,见后面的文章);栈信息读取源码文件的开销与并发;Recovery 写日志时的 isatty 颜色前缀(\\x1b[31m)在文件日志里的表现'],
    'Recovery')
